def guess_mime(p):
    mt,_=mimetypes.guess_type(p)
    if mt:
        return mt
    pl=p.lower()
    if pl.endswith('.css'):
        return 'text/css'
    if pl.endswith('.js'):
        return 'application/javascript'
    if pl.endswith('.png'):
        return 'image/png'
    if pl.endswith('.jpg') or pl.endswith('.jpeg'):
        return 'image/jpeg'
    if pl.endswith('.gif'):
        return 'image/gif'
    if pl.endswith('.svg'):
        return 'image/svg+xml'
    if pl.endswith('.woff2'):
        return 'font/woff2'
    if pl.endswith('.woff'):
        return 'font/woff'
    if pl.endswith('.ttf'):
        return 'font/ttf'
    if pl.endswith('.otf'):
        return 'font/otf'
    if pl.endswith('.mp3'):
        return 'audio/mpeg'
    if pl.endswith('.mp4'):
        return 'video/mp4'
    if pl.endswith('.webm'):
        return 'video/webm'
    if pl.endswith('.html') or pl.endswith('.htm'):
        return 'text/html'
    return 'application/octet-stream'

def make_data_url(content_bytes,mime):
    b64=base64.b64encode(content_bytes).decode('ascii')
    return f"data:{mime};base64,{b64}"

def parse_data_url(url):
    if not url.lower().startswith('data:'):
        return None
    try:
        header,data=url.split(',',1)
        header=header[5:]
        is_b64=False
        mime='text/plain'
        if ';base64' in header.lower():
            parts=header.split(';')
            if parts[0]:
                mime=parts[0]
            is_b64=True
        else:
            if header:
                mime=header
        if is_b64:
            try:
                decoded=base64.b64decode(data,validate=True)
            except Exception:
                decoded=b""
        else:
            decoded=urllib.parse.unquote_to_bytes(data)
        return mime,decoded
    except Exception:
        return None

def normalize_data_url(url):
    parsed=parse_data_url(url)
    if parsed is None:
        return url
    mime,data_bytes=parsed
    header_part=url.split(',',1)[0]
    mime_part=header_part[5:].split(';')[0] if ';' in header_part else header_part[5:]
    if not mime_part:
        mime_part='text/plain'
    # check base64 validity
    if ';base64' in header_part.lower():
        # if data part invalid, output empty
        try:
            base64.b64decode(url.split(',',1)[1],validate=True)
            # valid, re-encode to ensure same
            b64=base64.b64encode(data_bytes).decode()
            return f"data:{mime_part};base64,{b64}"
        except Exception:
            return f"data:{mime_part};base64,"
    else:
        b64=base64.b64encode(data_bytes).decode()
        return f"data:{mime_part if mime_part else 'text/plain'};base64,{b64}"

def is_data_url(u): return u.lower().startswith('data:')
def is_blob_url(u): return u.lower().startswith('blob:')
def is_javascript_url(u): return u.lower().strip().startswith('javascript:')
def is_mailto_url(u): return u.lower().startswith('mailto:')

def escape_attr_val(s):
    return s.replace('&','&amp;').replace('"','&quot;').replace('<','&lt;').replace('>','&gt;')

VOID_ELEMENTS={'area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr'}

def is_valid_url_for_fetch(url):
    try:
        p=urllib.parse.urlparse(url)
        return p.scheme in ('http','https','file')
    except:
        return False

def resolve_url(url, base_url_str, is_src=False):
    url=url.strip()
    if not url:
        return ""
    if url.startswith('#'):
        return url
    if is_mailto_url(url):
        return url
    if is_data_url(url):
        return url
    if is_blob_url(url):
        return ""
    if is_javascript_url(url):
        return url
    parsed=urllib.parse.urlparse(url)
    if parsed.scheme in ('http','https','ftp','file'):
        return url
    if not base_url_str:
        if is_src:
            return "data:text/plain;base64,"
        else:
            return "data:,"
    try:
        joined=urllib.parse.urljoin(base_url_str,url)
        return joined
    except Exception:
        if is_src:
            return "data:text/plain;base64,"
        else:
            return "data:,"

def domain_matches(entry, dom):
    entry=entry.lower()
    dom=dom.lower()
    if entry.startswith('.'):
        return dom.endswith(entry) or dom==entry[1:]
    else:
        return dom==entry or dom.endswith('.'+entry)

def is_url_allowed_by_domain(url, whitelist, is_blacklist):
    if not whitelist:
        return True
    try:
        parsed=urllib.parse.urlparse(url)
        domain=parsed.hostname or ""
        if not domain:
            return True
        if is_blacklist:
            for e in whitelist:
                if domain_matches(e,domain):
                    return False
            return True
        else:
            for e in whitelist:
                if domain_matches(e,domain):
                    return True
            return False
    except Exception:
        return True

def fetch_file_url(file_url):
    parsed=urllib.parse.urlparse(file_url)
    if parsed.scheme!='file':
        return None,None
    path=urllib.parse.unquote(parsed.path)
    p=pathlib.Path(path)
    if not p.is_file():
        return None,"file not found"
    try:
        data=p.read_bytes()
        mime=guess_mime(path)
        return data,mime
    except Exception as e:
        return None,str(e)

class MonolithParser(HTMLParser):
    def __init__(self, base_url_for_fetch, document_url, custom_base, options):
        super().__init__(convert_charrefs=False)
        self.base_url_for_fetch=base_url_for_fetch
        self.document_url=document_url
        self.custom_base=custom_base
        self.options=options
        self.output_parts=[]
        self.in_head=False
        self.head_seen=False
        self.base_tag_found=False
        self.base_href_original=None
        self.existing_base_href_for_fetch=None
        self.csp_needed={}
        self.stack=[]
        self.in_style=False
        self.style_content=[]
        self.in_script=False
        self.script_content=[]
        self.script_attrs=None
        self.skip_script_end=False
        self.logs=[]
        self.options_no_images=options.get('no_images',False)
        self.options_no_css=options.get('no_css',False)
        self.options_no_js=options.get('no_js',False)
        self.options_no_frames=options.get('no_frames',False)
        self.options_no_fonts=options.get('no_fonts',False)
        self.options_no_audio=options.get('no_audio',False)
        self.options_no_video=options.get('no_video',False)
        self.options_isolate=options.get('isolate',False)
        self.options_no_metadata=options.get('no_metadata',False)
        self.options_unwrap_noscript=options.get('unwrap_noscript',False)
        self.options_mhtml=options.get('mhtml',False)
        self.whitelist_domains=options.get('domains',[])
        self.is_blacklist=options.get('blacklist',False)
        self.effective_fetch_base=None
        if custom_base and is_valid_url_for_fetch(custom_base):
            self.effective_fetch_base=custom_base
        else:
            self.effective_fetch_base=document_url
        if base_url_for_fetch and is_valid_url_for_fetch(base_url_for_fetch):
            # if custom base valid, effective is base_url_for_fetch already, else document_url
            if custom_base and is_valid_url_for_fetch(custom_base):
                self.effective_fetch_base=base_url_for_fetch
            else:
                # base_url_for_fetch may be document_url
                self.effective_fetch_base=base_url_for_fetch
        else:
            # If base_url_for_fetch is None or invalid, use document_url for file targets
            if document_url:
                self.effective_fetch_base=document_url
            else:
                self.effective_fetch_base=None

    def handle_decl(self, decl):
        self.output_parts.append(f"<!{decl}>")

    def handle_comment(self, data):
        self.output_parts.append(f"<!--{data}-->")

    def build_attr_string(self, attrs):
        s=""
        for k,v in attrs:
            if v is None:
                s+=f" {k}"
            else:
                ev=escape_attr_val(v)
                s+=f' {k}="{ev}"'
        return s

    def fetch_asset(self, resolved_url):
        if not resolved_url:
            return None
        if is_data_url(resolved_url):
            return normalize_data_url(resolved_url)
        if is_blob_url(resolved_url):
            return None
        if not is_url_allowed_by_domain(resolved_url,self.whitelist_domains,self.is_blacklist):
            self.logs.append(f"{resolved_url} (blocked)")
            return None
        if resolved_url.startswith('file://'):
            if self.document_url is None:
                self.logs.append(f"{resolved_url} (security error)")
                return None
            if self.effective_fetch_base and (self.effective_fetch_base.startswith('http://') or self.effective_fetch_base.startswith('https://')):
                if resolved_url.startswith('file://'):
                    self.logs.append(f"{resolved_url} (security error)")
                    return None
            data,mime_or_err=fetch_file_url(resolved_url)
            if data is not None:
                self.logs.append(resolved_url)
                return make_data_url(data,mime_or_err)
            else:
                if mime_or_err=="file not found":
                    self.logs.append(f"{resolved_url} (file not found)")
                else:
                    self.logs.append(f"{resolved_url} ({mime_or_err})")
                return None
        elif resolved_url.startswith('http://') or resolved_url.startswith('https://'):
            self.logs.append(f"{resolved_url} (error sending request for url ({resolved_url}))")
            return None
        else:
            if resolved_url.startswith('data:'):
                return resolved_url
            return None

    def fetch_raw(self, resolved_url):
        if resolved_url.startswith('file://'):
            if self.document_url is None:
                return None
            if self.effective_fetch_base and (self.effective_fetch_base.startswith('http://') or self.effective_fetch_base.startswith('https://')):
                if resolved_url.startswith('file://'):
                    return None
            data,_=fetch_file_url(resolved_url)
            return data
        return None

    def fetch_css(self, resolved_url):
        if is_data_url(resolved_url):
            return normalize_data_url(resolved_url)
        if resolved_url.startswith('file://'):
            if self.document_url is None:
                return None
            if self.effective_fetch_base and (self.effective_fetch_base.startswith('http://') or self.effective_fetch_base.startswith('https://')):
                if resolved_url.startswith('file://'):
                    self.logs.append(f"{resolved_url} (security error)")
                    return None
            data,mime_or_err=fetch_file_url(resolved_url)
            if data is not None:
                self.logs.append(resolved_url)
                try:
                    css_text=data.decode('utf-8')
                except:
                    css_text=data.decode('latin-1',errors='replace')
                processed=self.process_css_text(css_text,resolved_url)
                return make_data_url(processed.encode('utf-8'),'text/css')
            else:
                if mime_or_err=="file not found":
                    self.logs.append(f"{resolved_url} (file not found)")
                else:
                    self.logs.append(f"{resolved_url} ({mime_or_err})")
                return None
        elif resolved_url.startswith('http://') or resolved_url.startswith('https://'):
            self.logs.append(f"{resolved_url} (error sending request for url ({resolved_url}))")
            return None
        else:
            return None

    def process_css_text(self, css_text, base_for_css):
        if self.options_no_css:
            return ""
        if self.options_no_fonts:
            css_text=re.sub(r'@font-face\s*{[^}]*}',' ',css_text,flags=re.IGNORECASE|re.DOTALL)
        # handle @import
        import_pattern=re.compile(r'@import\s+(?:url\([^\)]+\)|["\'][^"\']+["\'])[^;]*;',re.IGNORECASE)
        def repl_import(m):
            full=m.group(0)
            url=None
            mu=re.search(r'url\(\s*["\']?(.*?)["\']?\s*\)',full,re.IGNORECASE)
            if mu:
                url=mu.group(1)
                rest=full[mu.end():]
            else:
                ms=re.search(r'@import\s+["\'](.*?)["\']',full,re.IGNORECASE)
                if ms:
                    url=ms.group(1)
                    rest=full[ms.end():]
                else:
                    return full
            resolved=resolve_url(url,base_for_css,is_src=True)
            fetched=self.fetch_css(resolved)
            if fetched is not None:
                if 'url(' in full.lower():
                    return f'@import url("{fetched}"){rest}'
                else:
                    return f'@import "{fetched}"{rest}'
            else:
                if resolved.startswith('http://') or resolved.startswith('https://'):
                    return full
                else:
                    if 'url(' in full.lower():
                        return f'@import url(){rest}'
                    else:
                        return f'@import ""{rest}'
        css_text=import_pattern.sub(repl_import,css_text)

        # handle font-face extraction to avoid placeholder for fonts when -i
        font_blocks=[]
        def extract_ff(m):
            font_blocks.append(m.group(0))
            return f"__FF_{len(font_blocks)-1}__"
        ff_pat=re.compile(r'@font-face\s*{[^}]*}',re.IGNORECASE|re.DOTALL)
        if not self.options_no_fonts:
            css_text=ff_pat.sub(extract_ff,css_text)

        url_pat=re.compile(r'url\(\s*(?:"([^"]*)"|\'([^\']*)\'|([^\'"\)]+))\s*\)',re.IGNORECASE)
        def repl_url(m):
            url=m.group(1)
            if url is None: url=m.group(2)
            if url is None: url=m.group(3)
            if url is None: url=""
            url=url.strip()
            if not url:
                return 'url()'
            if is_data_url(url):
                return f'url("{normalize_data_url(url)}")'
            if is_blob_url(url):
                return 'url()'
            resolved=resolve_url(url,base_for_css,is_src=True)
            fetched=self.fetch_asset(resolved)
            if fetched is not None:
                if self.options_no_images and fetched.startswith('data:image/'):
                    return f'url("{PLACEHOLDER_PNG_URL}")'
                return f'url("{fetched}")'
            else:
                if resolved.startswith('http://') or resolved.startswith('https://'):
                    return f'url("{url}")'
                else:
                    if self.options_no_images:
                        return f'url("{PLACEHOLDER_PNG_URL}")'
                    return 'url()'
        css_text=url_pat.sub(repl_url,css_text)

        if not self.options_no_fonts:
            for i,block in enumerate(font_blocks):
                def repl_url_font(m):
                    url=m.group(1) or m.group(2) or m.group(3) or ""
                    url=url.strip()
                    if not url:
                        return 'url()'
                    if is_data_url(url):
                        return f'url("{normalize_data_url(url)}")'
                    if is_blob_url(url):
                        return 'url()'
                    resolved=resolve_url(url,base_for_css,is_src=True)
                    fetched=self.fetch_asset(resolved)
                    if fetched:
                        return f'url("{fetched}")'
                    else:
                        if resolved.startswith('http://') or resolved.startswith('https://'):
                            return f'url("{url}")'
                        else:
                            return 'url()'
                processed= url_pat.sub(repl_url_font, block)
                css_text=css_text.replace(f"__FF_{i}__",processed)
        return css_text

    def process_src_attr(self, src_val):
        if not src_val:
            return ""
        if is_data_url(src_val):
            return normalize_data_url(src_val)
        if is_blob_url(src_val):
            return None
        resolved=resolve_url(src_val,self.effective_fetch_base,is_src=True)
        if resolved.startswith('data:'):
            return resolved
        fetched=self.fetch_asset(resolved)
        if fetched:
            return fetched
        else:
            if resolved.startswith('http://') or resolved.startswith('https://'):
                return src_val
            else:
                return None

    def process_srcset_attr(self, srcset_val):
        if not srcset_val:
            return ""
        if self.options_no_images:
            # replace each with placeholder
            cands=srcset_val.split(',')
            new=[]
            for cand in cands:
                cand=cand.strip()
                if not cand:
                    continue
                parts=cand.split()
                if not parts:
                    continue
                desc=" ".join(parts[1:]) if len(parts)>1 else ""
                if desc:
                    new.append(f"{PLACEHOLDER_PNG_URL} {desc}")
                else:
                    new.append(PLACEHOLDER_PNG_URL)
            return ", ".join(new)
        cands=srcset_val.split(',')
        new_cands=[]
        for cand in cands:
            cand=cand.strip()
            if not cand:
                continue
            parts=cand.split()
            if not parts:
                continue
            url=parts[0]
            desc=" ".join(parts[1:]) if len(parts)>1 else ""
            if is_data_url(url):
                new_url=normalize_data_url(url)
            elif is_blob_url(url):
                continue
            else:
                resolved=resolve_url(url,self.effective_fetch_base,is_src=True)
                if resolved.startswith('data:'):
                    new_url=resolved
                else:
                    fetched=self.fetch_asset(resolved)
                    if fetched:
                        new_url=fetched
                    else:
                        if resolved.startswith('http://') or resolved.startswith('https://'):
                            new_url=url
                        else:
                            new_url=PLACEHOLDER_PNG_URL
            if desc:
                new_cands.append(f"{new_url} {desc}")
            else:
                new_cands.append(new_url)
        return ", ".join(new_cands)

    def process_iframe_src(self, src_val):
        if not src_val:
            return ""
        if is_data_url(src_val):
            return normalize_data_url(src_val)
        if is_blob_url(src_val):
            return None
        resolved=resolve_url(src_val,self.effective_fetch_base,is_src=True)
        if resolved.startswith('data:'):
            return resolved
        data=self.fetch_raw(resolved)
        if data is not None:
            b64=base64.b64encode(data).decode()
            return f"data:text/html;base64,{b64}"
        else:
            if resolved.startswith('http://') or resolved.startswith('https://'):
                return src_val
            else:
                return None

    def handle_data(self, data):
        if self.in_style:
            self.style_content.append(data)
        elif self.in_script:
            self.script_content.append(data)
        else:
            self.output_parts.append(data)

    def handle_starttag(self, tag, attrs):
        tl=tag.lower()
        self.stack.append(tl)
        if tl=='head':
            self.in_head=True
            self.head_seen=True
        if tl=='base':
            self.base_tag_found=True
            href=None
            for k,v in attrs:
                if k.lower()=='href':
                    href=v
                    break
            self.base_href_original=href
            if not self.custom_base and href:
                resolved=resolve_url(href,self.document_url,is_src=False) if self.document_url else href
                if is_valid_url_for_fetch(resolved) or resolved.startswith('file://') or resolved.startswith('http://') or resolved.startswith('https://'):
                    self.existing_base_href_for_fetch=resolved
                    if not self.custom_base:
                        self.effective_fetch_base=resolved
        if tl=='style':
            if self.options_no_css:
                if 'style-src' not in self.csp_needed:
                    self.csp_needed['style-src']="'none'"
                self.in_style=True
                self.style_content=[]
                attr_str=self.build_attr_string(attrs)
                self.output_parts.append(f"<{tag}{attr_str}>")
                return
            else:
                self.in_style=True
                self.style_content=[]
                attr_str=self.build_attr_string(attrs)
                self.output_parts.append(f"<{tag}{attr_str}>")
                return
        if tl=='script':
            src=None
            has_integrity=False
            for k,v in attrs:
                if k.lower()=='src':
                    src=v
                if k.lower()=='integrity':
                    has_integrity=True
            self.in_script=True
            self.script_content=[]
            if self.options_no_js:
                if 'script-src' not in self.csp_needed:
                    self.csp_needed['script-src']="'none'"
                self.output_parts.append("<script></script>")
                self.skip_script_end=True
                return
            else:
                if src is not None:
                    if has_integrity:
                        new_attrs=[]
                        for k,v in attrs:
                            if k.lower()=='integrity':
                                continue
                            new_attrs.append((k,v))
                        attr_str=self.build_attr_string(new_attrs)
                        self.output_parts.append(f"<{tag}{attr_str}></script>")
                        self.skip_script_end=True
                        return
                    else:
                        resolved=resolve_url(src,self.effective_fetch_base,is_src=True)
                        data=self.fetch_raw(resolved)
                        if data is not None:
                            try:
                                txt=data.decode('utf-8')
                            except:
                                txt=data.decode('latin-1',errors='replace')
                            new_attrs=[]
                            for k,v in attrs:
                                if k.lower()=='src' or k.lower()=='integrity':
                                    continue
                                new_attrs.append((k,v))
                            attr_str=self.build_attr_string(new_attrs)
                            self.output_parts.append(f"<{tag}{attr_str}>{txt}</script>")
                            self.skip_script_end=True
                            return
                        else:
                            if resolved.startswith('http://') or resolved.startswith('https://'):
                                attr_str=self.build_attr_string(attrs)
                                self.output_parts.append(f"<{tag}{attr_str}></script>")
                            else:
                                new_attrs=[]
                                for k,v in attrs:
                                    if k.lower()=='src' or k.lower()=='integrity':
                                        continue
                                    new_attrs.append((k,v))
                                attr_str=self.build_attr_string(new_attrs)
                                self.output_parts.append(f"<{tag}{attr_str}></script>")
                            self.skip_script_end=True
                            return
                else:
                    attr_str=self.build_attr_string(attrs)
                    self.output_parts.append(f"<{tag}{attr_str}>")
                    return
        # generic handling
        # Check no_css for link
        if tl=='link':
            rel_val=''
            for k,v in attrs:
                if k.lower()=='rel' and v:
                    rel_val=v
            rel_tokens=rel_val.lower().split() if rel_val else []
            if 'stylesheet' in rel_tokens:
                if self.options_no_css:
                    if 'style-src' not in self.csp_needed:
                        self.csp_needed['style-src']="'none'"
                    new_attrs=[]
                    for k,v in attrs:
                        if k.lower()=='href' or k.lower()=='integrity':
                            continue
                        new_attrs.append((k,v))
                    attr_str=self.build_attr_string(new_attrs)
                    self.output_parts.append(f"<{tag}{attr_str}>")
                    return
                # integrity check
                if any(k.lower()=='integrity' for k,_ in attrs):
                    new_attrs=[]
                    for k,v in attrs:
                        if k.lower()=='integrity':
                            continue
                        new_attrs.append((k,v))
                    attr_str=self.build_attr_string(new_attrs)
                    self.output_parts.append(f"<{tag}{attr_str}>")
                    return
                # embed
                href=None
                for k,v in attrs:
                    if k.lower()=='href':
                        href=v
                        break
                if href is None:
                    attr_str=self.build_attr_string(attrs)
                    self.output_parts.append(f"<{tag}{attr_str}>")
                    return
                resolved=resolve_url(href,self.effective_fetch_base,is_src=True)
                fetched=self.fetch_css(resolved)
                if fetched is not None:
                    new_attrs=[]
                    for k,v in attrs:
                        if k.lower()=='href':
                            new_attrs.append((k,fetched))
                        elif k.lower()=='integrity':
                            continue
                        else:
                            new_attrs.append((k,v))
                    attr_str=self.build_attr_string(new_attrs)
                    self.output_parts.append(f"<{tag}{attr_str}>")
                    return
                else:
                    if resolved.startswith('http://') or resolved.startswith('https://'):
                        new_attrs=[]
                        for k,v in attrs:
                            if k.lower()=='integrity':
                                continue
                            new_attrs.append((k,v))
                        attr_str=self.build_attr_string(new_attrs)
                        self.output_parts.append(f"<{tag}{attr_str}>")
                        return
                    else:
                        new_attrs=[]
                        for k,v in attrs:
                            if k.lower()=='href' or k.lower()=='integrity':
                                continue
                            new_attrs.append((k,v))
                        attr_str=self.build_attr_string(new_attrs)
                        self.output_parts.append(f"<{tag}{attr_str}>")
                        return
            elif 'icon' in rel_tokens:
                if self.options_no_images:
                    if 'img-src' not in self.csp_needed:
                        self.csp_needed['img-src']='data:'
                    new_attrs=[]
                    for k,v in attrs:
                        if k.lower()=='href':
                            continue
                        new_attrs.append((k,v))
                    attr_str=self.build_attr_string(new_attrs)
                    self.output_parts.append(f"<{tag}{attr_str}>")
                    return
                else:
                    href=None
                    for k,v in attrs:
                        if k.lower()=='href':
                            href=v
                            break
                    if href is None:
                        attr_str=self.build_attr_string(attrs)
                        self.output_parts.append(f"<{tag}{attr_str}>")
                        return
                    resolved=resolve_url(href,self.effective_fetch_base,is_src=True)
                    fetched=self.fetch_asset(resolved)
                    if fetched:
                        new_attrs=[]
                        for k,v in attrs:
                            if k.lower()=='href':
                                new_attrs.append((k,fetched))
                            else:
                                new_attrs.append((k,v))
                        attr_str=self.build_attr_string(new_attrs)
                        self.output_parts.append(f"<{tag}{attr_str}>")
                        return
                    else:
                        if resolved.startswith('http://') or resolved.startswith('https://'):
                            attr_str=self.build_attr_string(attrs)
                            self.output_parts.append(f"<{tag}{attr_str}>")
                            return
                        else:
                            new_attrs=[]
                            for k,v in attrs:
                                if k.lower()=='href':
                                    continue
                                new_attrs.append((k,v))
                            attr_str=self.build_attr_string(new_attrs)
                            self.output_parts.append(f"<{tag}{attr_str}>")
                            return
            else:
                # other link: convert href to absolute
                new_attrs=[]
                for k,v in attrs:
                    if k.lower()=='href':
                        resolved=resolve_url(v,self.effective_fetch_base,is_src=False)
                        new_attrs.append((k,resolved))
                    else:
                        new_attrs.append((k,v))
                attr_str=self.build_attr_string(new_attrs)
                self.output_parts.append(f"<{tag}{attr_str}>")
                return

        if tl in ('a','area'):
            new_attrs=[]
            for k,v in attrs:
                if k.lower()=='href':
                    if self.options_no_js and v.lstrip().startswith('javascript:'):
                        new_attrs.append((k,'javascript:;'))
                    else:
                        resolved=resolve_url(v,self.effective_fetch_base,is_src=False)
                        new_attrs.append((k,resolved))
                else:
                    if self.options_no_js and k.lower().startswith('on'):
                        continue
                    if self.options_no_css and k.lower()=='style':
                        continue
                    new_attrs.append((k,v))
            attr_str=self.build_attr_string(new_attrs)
            self.output_parts.append(f"<{tag}{attr_str}>")
            return

        if tl=='form':
            new_attrs=[]
            for k,v in attrs:
                if k.lower()=='action':
                    resolved=resolve_url(v,self.effective_fetch_base,is_src=False)
                    new_attrs.append((k,resolved))
                else:
                    if self.options_no_js and k.lower().startswith('on'):
                        continue
                    if self.options_no_css and k.lower()=='style':
                        continue
                    new_attrs.append((k,v))
            attr_str=self.build_attr_string(new_attrs)
            self.output_parts.append(f"<{tag}{attr_str}>")
            return

        if tl=='img':
            if self.options_no_images:
                if 'img-src' not in self.csp_needed:
                    self.csp_needed['img-src']='data:'
                new_attrs=[]
                for k,v in attrs:
                    lk=k.lower()
                    if lk=='src':
                        new_attrs.append((k,PLACEHOLDER_PNG_URL))
                    elif lk=='srcset':
                        # placeholder for each
                        cands=v.split(',')
                        nn=[]
                        for cand in cands:
                            cand=cand.strip()
                            if not cand:
                                continue
                            parts=cand.split()
                            desc=" ".join(parts[1:]) if len(parts)>1 else ""
                            if desc:
                                nn.append(f"{PLACEHOLDER_PNG_URL} {desc}")
                            else:
                                nn.append(PLACEHOLDER_PNG_URL)
                        new_attrs.append((k,", ".join(nn)))
                    else:
                        if self.options_no_js and lk.startswith('on'):
                            continue
                        if self.options_no_css and lk=='style':
                            continue
                        new_attrs.append((k,v))
                attr_str=self.build_attr_string(new_attrs)
                self.output_parts.append(f"<{tag}{attr_str}>")
                return
            else:
                new_attrs=[]
                for k,v in attrs:
                    lk=k.lower()
                    if lk=='src':
                        proc=self.process_src_attr(v)
                        if proc is None:
                            # decide keep or remove
                            resolved=resolve_url(v,self.effective_fetch_base,is_src=True)
                            if resolved.startswith('http://') or resolved.startswith('https://'):
                                new_attrs.append((k,v))
                            else:
                                pass
                        else:
                            if proc=="":
                                pass
                            else:
                                new_attrs.append((k,proc))
                    elif lk=='srcset':
                        proc=self.process_srcset_attr(v)
                        new_attrs.append((k,proc))
                    else:
                        if self.options_no_js and lk.startswith('on'):
                            continue
                        if self.options_no_css and lk=='style':
                            continue
                        if lk=='style':
                            # process css
                            base=self.effective_fetch_base
                            # style content is v
                            # need to process url()
                            # Use process_css_text but for style attr it's CSS declarations
                            # We'll process urls inside
                            processed=self.process_css_text(v,base) if not self.options_no_css else ""
                            new_attrs.append((k,processed))
                        else:
                            new_attrs.append((k,v))
                attr_str=self.build_attr_string(new_attrs)
                self.output_parts.append(f"<{tag}{attr_str}>")
                return

        if tl=='source':
            parent_is_picture=any(t=='picture' for t in self.stack[:-1])
            parent_is_video=any(t=='video' for t in self.stack[:-1])
            parent_is_audio=any(t=='audio' for t in self.stack[:-1])
            if parent_is_picture:
                if self.options_no_images:
                    if 'img-src' not in self.csp_needed:
                        self.csp_needed['img-src']='data:'
                    new_attrs=[]
                    for k,v in attrs:
                        lk=k.lower()
                        if lk=='src':
                            new_attrs.append((k,PLACEHOLDER_PNG_URL))
                        elif lk=='srcset':
                            cands=v.split(',')
                            nn=[]
                            for cand in cands:
                                cand=cand.strip()
                                if not cand:
                                    continue
                                parts=cand.split()
                                desc=" ".join(parts[1:]) if len(parts)>1 else ""
                                if desc:
                                    nn.append(f"{PLACEHOLDER_PNG_URL} {desc}")
                                else:
                                    nn.append(PLACEHOLDER_PNG_URL)
                            new_attrs.append((k,", ".join(nn)))
                        else:
                            new_attrs.append((k,v))
                    attr_str=self.build_attr_string(new_attrs)
                    self.output_parts.append(f"<{tag}{attr_str}>")
                    return
                else:
                    new_attrs=[]
                    for k,v in attrs:
                        lk=k.lower()
                        if lk=='srcset':
                            new_attrs.append((k,self.process_srcset_attr(v)))
                        elif lk=='src':
                            proc=self.process_src_attr(v)
                            if proc is None:
                                resolved=resolve_url(v,self.effective_fetch_base,is_src=True)
                                if resolved.startswith('http://') or resolved.startswith('https://'):
                                    new_attrs.append((k,v))
                            else:
                                if proc!="":
                                    new_attrs.append((k,proc))
                        else:
                            new_attrs.append((k,v))
                    attr_str=self.build_attr_string(new_attrs)
                    self.output_parts.append(f"<{tag}{attr_str}>")
                    return
            else:
                if parent_is_video and self.options_no_video:
                    new_attrs=[]
                    for k,v in attrs:
                        if k.lower() in ('src','srcset'):
                            continue
                        new_attrs.append((k,v))
                    attr_str=self.build_attr_string(new_attrs)
                    self.output_parts.append(f"<{tag}{attr_str}>")
                    return
                if parent_is_audio and self.options_no_audio:
                    new_attrs=[]
                    for k,v in attrs:
                        if k.lower() in ('src','srcset'):
                            continue
                        new_attrs.append((k,v))
                    attr_str=self.build_attr_string(new_attrs)
