        # Check robots
        has_robots=bool(re.search(r'<meta[^>]*name=["\']?robots["\']?',html_str,re.IGNORECASE))
        has_robots_content_none=False
        # For existing robots, check if content already none? Actually we need to find first robots meta and set its content to none if not already? Original behavior:
        # If robots meta exists, first one's content becomes none if not already? Observed: <meta name="robots" content="index"> becomes <meta name="robots" content="none"> (content replaced, no closing)
