                self.csp_needed['img-src']='data:'

        # Note: mhtml also implies script-src none, but we already set no_js true for mhtml, so it will be included

        csp_parts=[]
        for key in csp_order:
            if key in self.csp_needed:
                csp_parts.append(f"{key} {self.csp_needed[key]};")
        csp_meta=""
        if csp_parts:
            csp_content=" ".join(csp_parts)
            csp_meta=f'<meta http-equiv="Content-Security-Policy" content="{csp_content}"></meta>'

        # base handling
        base_meta=""
        if self.custom_base:
            if self.base_tag_found:
                # replace href in existing base
                def repl_base(m):
                    tag_text=m.group(0)
                    if re.search(r'href\s*=',tag_text,re.IGNORECASE):
                        new_tag=re.sub(r'href\s*=\s*("[^"]*"|\'[^\']*\'|[^\s>]+)', f'href="{escape_attr_val(self.custom_base)}"', tag_text, flags=re.IGNORECASE)
