                if base_meta:
                    head_content+=base_meta
                if robots_meta:
                    head_content+=robots_meta
                html_str=html_str[:insert_pos]+f"<head>{head_content}</head>"+html_str[insert_pos:]
                csp_meta=base_meta=robots_meta=""
            else:
                head_content=""
                if csp_meta:
