                    head_end_match=re.search(r'</head>',html_str,re.IGNORECASE)
                if base_meta:
                    html_str=html_str[:head_end_match.start()]+base_meta+html_str[head_end_match.start():]
                    head_end_match=re.search(r'</head>',html_str,re.IGNORECASE)
                if robots_meta:
                    html_str=html_str[:head_end_match.start()]+robots_meta+html_str[head_end_match.start():]
            else:
                # no </head>
                if csp_meta:
                    html_str=html_str[:head_match.end()]+csp_meta+html_str[head_match.end():]
                if base_meta:
                    html_str+=base_meta
