                if resolved_url.startswith('file://'):
                    return None
            data,_=fetch_file_url(resolved_url)
            return data
        return None

    def fetch_css(self, resolved_url):
        if is_data_url(resolved_url):
            return normalize_data_url(resolved_url)
        if resolved_url.startswith('file://'):
            if self.document_url is None:
                return None
            if self.effective_fetch_base and (self.effective_fetch_base.startswith('http://') or self.effective_fetch_base.startswith('https://')):
                if resolved_url.startswith('file://'):
                    self.logs.append(f"{resolved_url} (security error)")
                    return None
            data,mime_or_err=fetch_file_url(resolved_url)
            if data is not None:
                self.logs.append(resolved_url)
                try:
                    css_text=data.decode('utf-8')
                except:
                    css_text=data.decode('latin-1',errors='replace')
                processed=self.process_css_text(css_text,resolved_url)
                return make_data_url(processed.encode('utf-8'),'text/css')
            else:
                if mime_or_err=="file not found":
                    self.logs.append(f"{resolved_url} (file not found)")
                else:
                    self.logs.append(f"{resolved_url} ({mime_or_err})")
                return None
        elif resolved_url.startswith('http://') or resolved_url.startswith('https://'):
            self.logs.append(f"{resolved_url} (error sending request for url ({resolved_url}))")
            return None
        else:
            return None

    def process_css_text(self, css_text, base_for_css):
        if self.options_no_css:
            return ""
        if self.options_no_fonts:
            css_text=re.sub(r'@font-face\s*{[^}]*}',' ',css_text,flags=re.IGNORECASE|re.DOTALL)
        # handle @import
        import_pattern=re.compile(r'@import\s+(?:url\([^\)]+\)|["\'][^"\']+["\'])[^;]*;',re.IGNORECASE)
        def repl_import(m):
            full=m.group(0)
            url=None
            mu=re.search(r'url\(\s*["\']?(.*?)["\']?\s*\)',full,re.IGNORECASE)
            if mu:
                url=mu.group(1)
                rest=full[mu.end():]
            else:
                ms=re.search(r'@import\s+["\'](.*?)["\']',full,re.IGNORECASE)
                if ms:
                    url=ms.group(1)
                    rest=full[ms.end():]
                else:
                    return full
            resolved=resolve_url(url,base_for_css,is_src=True)
            fetched=self.fetch_css(resolved)
            if fetched is not None:
                if 'url(' in full.lower():
                    return f'@import url("{fetched}"){rest}'
                else:
                    return f'@import "{fetched}"{rest}'
            else:
                if resolved.startswith('http://') or resolved.startswith('https://'):
                    return full
                else:
                    if 'url(' in full.lower():
                        return f'@import url(){rest}'
                    else:
                        return f'@import ""{rest}'
        css_text=import_pattern.sub(repl_import,css_text)

        # handle font-face extraction to avoid placeholder for fonts when -i
        font_blocks=[]
        def extract_ff(m):
            font_blocks.append(m.group(0))
            return f"__FF_{len(font_blocks)-1}__"
        ff_pat=re.compile(r'@font-face\s*{[^}]*}',re.IGNORECASE|re.DOTALL)
        if not self.options_no_fonts:
            css_text=ff_pat.sub(extract_ff,css_text)

        url_pat=re.compile(r'url\(\s*(?:"([^"]*)"|\'([^\']*)\'|([^\'"\)]+))\s*\)',re.IGNORECASE)
        def repl_url(m):
            url=m.group(1)
            if url is None: url=m.group(2)
            if url is None: url=m.group(3)
            if url is None: url=""
            url=url.strip()
            if not url:
                return 'url()'
            if is_data_url(url):
                return f'url("{normalize_data_url(url)}")'
            if is_blob_url(url):
                return 'url()'
            resolved=resolve_url(url,base_for_css,is_src=True)
            fetched=self.fetch_asset(resolved)
            if fetched is not None:
                if self.options_no_images and fetched.startswith('data:image/'):
                    return f'url("{PLACEHOLDER_PNG_URL}")'
                return f'url("{fetched}")'
            else:
                if resolved.startswith('http://') or resolved.startswith('https://'):
                    return f'url("{url}")'
                else:
                    if self.options_no_images:
                        return f'url("{PLACEHOLDER_PNG_URL}")'
                    return 'url()'
        css_text=url_pat.sub(repl_url,css_text)

        if not self.options_no_fonts:
            for i,block in enumerate(font_blocks):
                def repl_url_font(m):
                    url=m.group(1) or m.group(2) or m.group(3) or ""
                    url=url.strip()
                    if not url:
                        return 'url()'
                    if is_data_url(url):
                        return f'url("{normalize_data_url(url)}")'
                    if is_blob_url(url):
                        return 'url()'
                    resolved=resolve_url(url,base_for_css,is_src=True)
                    fetched=self.fetch_asset(resolved)
                    if fetched:
                        return f'url("{fetched}")'
                    else:
                        if resolved.startswith('http://') or resolved.startswith('https://'):
                            return f'url("{url}")'
                        else:
                            return 'url()'
                processed= url_pat.sub(repl_url_font, block)
                css_text=css_text.replace(f"__FF_{i}__",processed)
        return css_text

    def process_src_attr(self, src_val):
        if not src_val:
            return ""
        if is_data_url(src_val):
            return normalize_data_url(src_val)
        if is_blob_url(src_val):
            return None
        resolved=resolve_url(src_val,self.effective_fetch_base,is_src=True)
        if resolved.startswith('data:'):
            return resolved
        fetched=self.fetch_asset(resolved)
        if fetched:
            return fetched
        else:
            if resolved.startswith('http://') or resolved.startswith('https://'):
                return src_val
            else:
                return None

    def process_srcset_attr(self, srcset_val):
        if not srcset_val:
            return ""
        if self.options_no_images:
            # replace each with placeholder
            cands=srcset_val.split(',')
            new=[]
            for cand in cands:
                cand=cand.strip()
                if not cand:
                    continue
                parts=cand.split()
                if not parts:
                    continue
                desc=" ".join(parts[1:]) if len(parts)>1 else ""
                if desc:
                    new.append(f"{PLACEHOLDER_PNG_URL} {desc}")
                else:
                    new.append(PLACEHOLDER_PNG_URL)
            return ", ".join(new)
        cands=srcset_val.split(',')
        new_cands=[]
        for cand in cands:
            cand=cand.strip()
            if not cand:
                continue
            parts=cand.split()
            if not parts:
                continue
            url=parts[0]
            desc=" ".join(parts[1:]) if len(parts)>1 else ""
            if is_data_url(url):
                new_url=normalize_data_url(url)
            elif is_blob_url(url):
                continue
            else:
                resolved=resolve_url(url,self.effective_fetch_base,is_src=True)
                if resolved.startswith('data:'):
                    new_url=resolved
                else:
                    fetched=self.fetch_asset(resolved)
                    if fetched:
                        new_url=fetched
                    else:
                        if resolved.startswith('http://') or resolved.startswith('https://'):
                            new_url=url
                        else:
                            new_url=PLACEHOLDER_PNG_URL
            if desc:
                new_cands.append(f"{new_url} {desc}")
            else:
                new_cands.append(new_url)
        return ", ".join(new_cands)

    def process_iframe_src(self, src_val):
        if not src_val:
            return ""
        if is_data_url(src_val):
            return normalize_data_url(src_val)
        if is_blob_url(src_val):
            return None
        resolved=resolve_url(src_val,self.effective_fetch_base,is_src=True)
        if resolved.startswith('data:'):
            return resolved
        data=self.fetch_raw(resolved)
        if data is not None:
            b64=base64.b64encode(data).decode()
            return f"data:text/html;base64,{b64}"
        else:
            if resolved.startswith('http://') or resolved.startswith('https://'):
                return src_val
            else:
                return None

    def handle_data(self, data):
        if self.in_style:
            self.style_content.append(data)
        elif self.in_script:
            self.script_content.append(data)
        else:
            self.output_parts.append(data)

    def handle_starttag(self, tag, attrs):
        tl=tag.lower()
        self.stack.append(tl)
        if tl=='head':
            self.in_head=True
            self.head_seen=True
        if tl=='base':
            self.base_tag_found=True
            href=None
            for k,v in attrs:
                if k.lower()=='href':
                    href=v
                    break
            self.base_href_original=href
            if not self.custom_base and href:
                resolved=resolve_url(href,self.document_url,is_src=False) if self.document_url else href
                if is_valid_url_for_fetch(resolved) or resolved.startswith('file://') or resolved.startswith('http://') or resolved.startswith('https://'):
                    self.existing_base_href_for_fetch=resolved
                    if not self.custom_base:
                        self.effective_fetch_base=resolved
        if tl=='style':
            if self.options_no_css:
                if 'style-src' not in self.csp_needed:
                    self.csp_needed['style-src']="'none'"
                self.in_style=True
                self.style_content=[]
                attr_str=self.build_attr_string(attrs)
                self.output_parts.append(f"<{tag}{attr_str}>")
                return
            else:
                self.in_style=True
                self.style_content=[]
                attr_str=self.build_attr_string(attrs)
                self.output_parts.append(f"<{tag}{attr_str}>")
                return
        if tl=='script':
            src=None
            has_integrity=False
            for k,v in attrs:
                if k.lower()=='src':
                    src=v
                if k.lower()=='integrity':
                    has_integrity=True
            self.in_script=True
            self.script_content=[]
            if self.options_no_js:
                if 'script-src' not in self.csp_needed:
                    self.csp_needed['script-src']="'none'"
                self.output_parts.append("<script></script>")
                self.skip_script_end=True
                return
            else:
                if src is not None:
                    if has_integrity:
                        new_attrs=[]
                        for k,v in attrs:
                            if k.lower()=='integrity':
                                continue
                            new_attrs.append((k,v))
                        attr_str=self.build_attr_string(new_attrs)
                        self.output_parts.append(f"<{tag}{attr_str}></script>")
                        self.skip_script_end=True
                        return
                    else:
                        resolved=resolve_url(src,self.effective_fetch_base,is_src=True)
                        data=self.fetch_raw(resolved)
                        if data is not None:
                            try:
                                txt=data.decode('utf-8')
                            except:
                                txt=data.decode('latin-1',errors='replace')
                            new_attrs=[]
                            for k,v in attrs:
                                if k.lower()=='src' or k.lower()=='integrity':
                                    continue
                                new_attrs.append((k,v))
                            attr_str=self.build_attr_string(new_attrs)
                            self.output_parts.append(f"<{tag}{attr_str}>{txt}</script>")
                            self.skip_script_end=True
                            return
                        else:
                            if resolved.startswith('http://') or resolved.startswith('https://'):
                                attr_str=self.build_attr_string(attrs)
                                self.output_parts.append(f"<{tag}{attr_str}></script>")
                            else:
                                new_attrs=[]
                                for k,v in attrs:
                                    if k.lower()=='src' or k.lower()=='integrity':
                                        continue
                                    new_attrs.append((k,v))
                                attr_str=self.build_attr_string(new_attrs)
                                self.output_parts.append(f"<{tag}{attr_str}></script>")
                            self.skip_script_end=True
                            return
                else:
                    attr_str=self.build_attr_string(attrs)
                    self.output_parts.append(f"<{tag}{attr_str}>")
                    return
        # generic handling
        # Check no_css for link
        if tl=='link':
            rel_val=''
            for k,v in attrs:
                if k.lower()=='rel' and v:
                    rel_val=v
            rel_tokens=rel_val.lower().split() if rel_val else []
            if 'stylesheet' in rel_tokens:
                if self.options_no_css:
                    if 'style-src' not in self.csp_needed:
                        self.csp_needed['style-src']="'none'"
                    new_attrs=[]
                    for k,v in attrs:
                        if k.lower()=='href' or k.lower()=='integrity':
                            continue
                        new_attrs.append((k,v))
                    attr_str=self.build_attr_string(new_attrs)
                    self.output_parts.append(f"<{tag}{attr_str}>")
                    return
                # integrity check
                if any(k.lower()=='integrity' for k,_ in attrs):
                    new_attrs=[]
                    for k,v in attrs:
                        if k.lower()=='integrity':
                            continue
                        new_attrs.append((k,v))
                    attr_str=self.build_attr_string(new_attrs)
                    self.output_parts.append(f"<{tag}{attr_str}>")
                    return
                # embed
                href=None
                for k,v in attrs:
                    if k.lower()=='href':
                        href=v
                        break
                if href is None:
                    attr_str=self.build_attr_string(attrs)
                    self.output_parts.append(f"<{tag}{attr_str}>")
                    return
                resolved=resolve_url(href,self.effective_fetch_base,is_src=True)
                fetched=self.fetch_css(resolved)
                if fetched is not None:
                    new_attrs=[]
                    for k,v in attrs:
                        if k.lower()=='href':
                            new_attrs.append((k,fetched))
                        elif k.lower()=='integrity':
                            continue
                        else:
                            new_attrs.append((k,v))
                    attr_str=self.build_attr_string(new_attrs)
                    self.output_parts.append(f"<{tag}{attr_str}>")
                    return
                else:
                    if resolved.startswith('http://') or resolved.startswith('https://'):
                        new_attrs=[]
                        for k,v in attrs:
                            if k.lower()=='integrity':
                                continue
                            new_attrs.append((k,v))
                        attr_str=self.build_attr_string(new_attrs)
                        self.output_parts.append(f"<{tag}{attr_str}>")
                        return
                    else:
                        new_attrs=[]
                        for k,v in attrs:
                            if k.lower()=='href' or k.lower()=='integrity':
                                continue
                            new_attrs.append((k,v))
                        attr_str=self.build_attr_string(new_attrs)
                        self.output_parts.append(f"<{tag}{attr_str}>")
                        return
            elif 'icon' in rel_tokens:
                if self.options_no_images:
                    if 'img-src' not in self.csp_needed:
                        self.csp_needed['img-src']='data:'
                    new_attrs=[]
                    for k,v in attrs:
                        if k.lower()=='href':
                            continue
                        new_attrs.append((k,v))
                    attr_str=self.build_attr_string(new_attrs)
                    self.output_parts.append(f"<{tag}{attr_str}>")
                    return
                else:
                    href=None
                    for k,v in attrs:
                        if k.lower()=='href':
                            href=v
                            break
                    if href is None:
                        attr_str=self.build_attr_string(attrs)
                        self.output_parts.append(f"<{tag}{attr_str}>")
                        return
                    resolved=resolve_url(href,self.effective_fetch_base,is_src=True)
                    fetched=self.fetch_asset(resolved)
                    if fetched:
                        new_attrs=[]
                        for k,v in attrs:
                            if k.lower()=='href':
                                new_attrs.append((k,fetched))
                            else:
                                new_attrs.append((k,v))
                        attr_str=self.build_attr_string(new_attrs)
                        self.output_parts.append(f"<{tag}{attr_str}>")
                        return
                    else:
                        if resolved.startswith('http://') or resolved.startswith('https://'):
                            attr_str=self.build_attr_string(attrs)
                            self.output_parts.append(f"<{tag}{attr_str}>")
                            return
                        else:
                            new_attrs=[]
                            for k,v in attrs:
                                if k.lower()=='href':
                                    continue
                                new_attrs.append((k,v))
                            attr_str=self.build_attr_string(new_attrs)
                            self.output_parts.append(f"<{tag}{attr_str}>")
                            return
            else:
                # other link: convert href to absolute
                new_attrs=[]
                for k,v in attrs:
                    if k.lower()=='href':
                        resolved=resolve_url(v,self.effective_fetch_base,is_src=False)
                        new_attrs.append((k,resolved))
                    else:
                        new_attrs.append((k,v))
                attr_str=self.build_attr_string(new_attrs)
                self.output_parts.append(f"<{tag}{attr_str}>")
                return

        if tl in ('a','area'):
            new_attrs=[]
            for k,v in attrs:
                if k.lower()=='href':
                    if self.options_no_js and v.lstrip().startswith('javascript:'):
                        new_attrs.append((k,'javascript:;'))
                    else:
                        resolved=resolve_url(v,self.effective_fetch_base,is_src=False)
                        new_attrs.append((k,resolved))
                else:
                    if self.options_no_js and k.lower().startswith('on'):
                        continue
                    if self.options_no_css and k.lower()=='style':
                        continue
                    new_attrs.append((k,v))
            attr_str=self.build_attr_string(new_attrs)
            self.output_parts.append(f"<{tag}{attr_str}>")
            return

        if tl=='form':
            new_attrs=[]
            for k,v in attrs:
                if k.lower()=='action':
                    resolved=resolve_url(v,self.effective_fetch_base,is_src=False)
                    new_attrs.append((k,resolved))
                else:
                    if self.options_no_js and k.lower().startswith('on'):
                        continue
                    if self.options_no_css and k.lower()=='style':
                        continue
                    new_attrs.append((k,v))
            attr_str=self.build_attr_string(new_attrs)
            self.output_parts.append(f"<{tag}{attr_str}>")
            return

        if tl=='img':
            if self.options_no_images:
                if 'img-src' not in self.csp_needed:
                    self.csp_needed['img-src']='data:'
                new_attrs=[]
                for k,v in attrs:
                    lk=k.lower()
                    if lk=='src':
                        new_attrs.append((k,PLACEHOLDER_PNG_URL))
                    elif lk=='srcset':
                        # placeholder for each
                        cands=v.split(',')
                        nn=[]
                        for cand in cands:
                            cand=cand.strip()
                            if not cand:
                                continue
                            parts=cand.split()
                            desc=" ".join(parts[1:]) if len(parts)>1 else ""
                            if desc:
                                nn.append(f"{PLACEHOLDER_PNG_URL} {desc}")
                            else:
                                nn.append(PLACEHOLDER_PNG_URL)
                        new_attrs.append((k,", ".join(nn)))
                    else:
                        if self.options_no_js and lk.startswith('on'):
                            continue
                        if self.options_no_css and lk=='style':
                            continue
                        new_attrs.append((k,v))
                attr_str=self.build_attr_string(new_attrs)
                self.output_parts.append(f"<{tag}{attr_str}>")
                return
            else:
                new_attrs=[]
                for k,v in attrs:
                    lk=k.lower()
                    if lk=='src':
                        proc=self.process_src_attr(v)
                        if proc is None:
                            # decide keep or remove
                            resolved=resolve_url(v,self.effective_fetch_base,is_src=True)
                            if resolved.startswith('http://') or resolved.startswith('https://'):
                                new_attrs.append((k,v))
                            else:
                                pass
                        else:
                            if proc=="":
                                pass
                            else:
                                new_attrs.append((k,proc))
                    elif lk=='srcset':
                        proc=self.process_srcset_attr(v)
                        new_attrs.append((k,proc))
                    else:
                        if self.options_no_js and lk.startswith('on'):
                            continue
                        if self.options_no_css and lk=='style':
                            continue
                        if lk=='style':
                            # process css
                            base=self.effective_fetch_base
                            # style content is v
                            # need to process url()
                            # Use process_css_text but for style attr it's CSS declarations
                            # We'll process urls inside
                            processed=self.process_css_text(v,base) if not self.options_no_css else ""
                            new_attrs.append((k,processed))
                        else:
                            new_attrs.append((k,v))
                attr_str=self.build_attr_string(new_attrs)
                self.output_parts.append(f"<{tag}{attr_str}>")
                return

        if tl=='source':
            parent_is_picture=any(t=='picture' for t in self.stack[:-1])
            parent_is_video=any(t=='video' for t in self.stack[:-1])
            parent_is_audio=any(t=='audio' for t in self.stack[:-1])
            if parent_is_picture:
                if self.options_no_images:
                    if 'img-src' not in self.csp_needed:
                        self.csp_needed['img-src']='data:'
                    new_attrs=[]
                    for k,v in attrs:
                        lk=k.lower()
                        if lk=='src':
                            new_attrs.append((k,PLACEHOLDER_PNG_URL))
                        elif lk=='srcset':
                            cands=v.split(',')
                            nn=[]
                            for cand in cands:
                                cand=cand.strip()
                                if not cand:
                                    continue
                                parts=cand.split()
                                desc=" ".join(parts[1:]) if len(parts)>1 else ""
                                if desc:
                                    nn.append(f"{PLACEHOLDER_PNG_URL} {desc}")
                                else:
                                    nn.append(PLACEHOLDER_PNG_URL)
                            new_attrs.append((k,", ".join(nn)))
                        else:
                            new_attrs.append((k,v))
                    attr_str=self.build_attr_string(new_attrs)
                    self.output_parts.append(f"<{tag}{attr_str}>")
                    return
                else:
                    new_attrs=[]
                    for k,v in attrs:
                        lk=k.lower()
                        if lk=='srcset':
                            new_attrs.append((k,self.process_srcset_attr(v)))
                        elif lk=='src':
                            proc=self.process_src_attr(v)
                            if proc is None:
                                resolved=resolve_url(v,self.effective_fetch_base,is_src=True)
                                if resolved.startswith('http://') or resolved.startswith('https://'):
                                    new_attrs.append((k,v))
                            else:
                                if proc!="":
                                    new_attrs.append((k,proc))
                        else:
                            new_attrs.append((k,v))
                    attr_str=self.build_attr_string(new_attrs)
                    self.output_parts.append(f"<{tag}{attr_str}>")
                    return
            else:
                if parent_is_video and self.options_no_video:
                    new_attrs=[]
                    for k,v in attrs:
                        if k.lower() in ('src','srcset'):
                            continue
                        new_attrs.append((k,v))
                    attr_str=self.build_attr_string(new_attrs)
                    self.output_parts.append(f"<{tag}{attr_str}>")
                    return
                if parent_is_audio and self.options_no_audio:
                    new_attrs=[]
                    for k,v in attrs:
                        if k.lower() in ('src','srcset'):
                            continue
                        new_attrs.append((k,v))
                    attr_str=self.build_attr_string(new_attrs)
                    self.output_parts.append(f"<{tag}{attr_str}>")
                    return
                new_attrs=[]
                for k,v in attrs:
                    lk=k.lower()
                    if lk=='src':
                        proc=self.process_src_attr(v)
                        if proc is None:
                            resolved=resolve_url(v,self.effective_fetch_base,is_src=True)
                            if resolved.startswith('http://') or resolved.startswith('https://'):
                                new_attrs.append((k,v))
                        else:
                            if proc!="":
                                new_attrs.append((k,proc))
                    elif lk=='srcset':
                        new_attrs.append((k,self.process_srcset_attr(v)))
                    else:
                        new_attrs.append((k,v))
