            self.in_head=False
        if tl=='style' and self.in_style:
            css_text="".join(self.style_content)
            if self.options_no_css:
                self.output_parts.append("</style>")
            else:
                processed=self.process_css_text(css_text,self.effective_fetch_base)
                self.output_parts.append(processed)
                self.output_parts.append("</style>")
            self.in_style=False
            self.style_content=[]
            return
        if tl=='script' and self.in_script:
            if self.skip_script_end:
                self.skip_script_end=False
                self.in_script=False
                self.script_content=[]
                return
            txt="".join(self.script_content)
            if self.options_no_js:
                self.output_parts.append("</script>")
            else:
                self.output_parts.append(txt)
                self.output_parts.append("</script>")
            self.in_script=False
            self.script_content=[]
            return
        if tl=='image' or tl=='use':
            # Check if we skipped due to -i
            if self.stack and self.stack[-1]=='__skip_image__':
                self.stack.pop()
                return
        # For noscript unwrap, handle replacement in finalize
        if tl=='noscript':
            if self.options_unwrap_noscript:
                # We'll replace in finalize
                self.output_parts.append(f"</{tag}>")
                return
        if tl in VOID_ELEMENTS:
            return
        self.output_parts.append(f"</{tag}>")

    def finalize(self):
        html_str="".join(self.output_parts)
