        if has_robots:
            # Replace first occurrence content
            def repl_first_robots(m):
                full=m.group(0)
                # Replace content="..." with content="none" preserving case of attribute name? Use lower?
                # Keep original case of tag but set content to none
                # Replace content attr
                new_tag=re.sub(r'content\s*=\s*("[^"]*"|\'[^\']*\'|[^\s>]+)', 'content="none"', full, flags=re.IGNORECASE, count=1)
                # If no content attr, add?
                if 'content=' not in new_tag.lower():
                    # add content
                    new_tag=new_tag.rstrip('>').rstrip('/')+ ' content="none">'
                return new_tag
            # Only replace first
            html_str=re.sub(r'<meta[^>]*name=["\']?robots["\']?[^>]*>', repl_first_robots, html_str, count=1, flags=re.IGNORECASE)
            robots_meta=""
        else:
            robots_meta='<meta name="robots" content="none"></meta>'

        # CSP
        csp_order=['default-src','style-src','font-src','frame-src','child-src','script-src','img-src']
        # Add isolate and flags
        if self.options_isolate:
            if 'default-src' not in self.csp_needed:
                self.csp_needed['default-src']="'unsafe-eval' 'unsafe-inline' data:;"
        if self.options_no_css:
            if 'style-src' not in self.csp_needed:
