                self.csp_needed['frame-src']="'none'"
                self.csp_needed['child-src']="'none'"
        if self.options_no_js:
            if 'script-src' not in self.csp_needed:
                self.csp_needed['script-src']="'none'"
        if self.options_no_images:
            if 'img-src' not in self.csp_needed:
                self.csp_needed['img-src']='data:'

        # Note: mhtml also implies script-src none, but we already set no_js true for mhtml, so it will be included

        csp_parts=[]
        for key in csp_order:
            if key in self.csp_needed:
                csp_parts.append(f"{key} {self.csp_needed[key]};")
        csp_meta=""
        if csp_parts:
            csp_content=" ".join(csp_parts)
            csp_meta=f'<meta http-equiv="Content-Security-Policy" content="{csp_content}"></meta>'

        # base handling
        base_meta=""
        if self.custom_base:
            if self.base_tag_found:
                # replace href in existing base
                def repl_base(m):
                    tag_text=m.group(0)
                    if re.search(r'href\s*=',tag_text,re.IGNORECASE):
                        new_tag=re.sub(r'href\s*=\s*("[^"]*"|\'[^\']*\'|[^\s>]+)', f'href="{escape_attr_val(self.custom_base)}"', tag_text, flags=re.IGNORECASE)
                        return new_tag
                    else:
                        return tag_text.replace('>',f' href="{escape_attr_val(self.custom_base)}">',1)
                html_str=re.sub(r'<base[^>]*>',repl_base,html_str,count=1,flags=re.IGNORECASE)
            else:
                base_meta=f'<base href="{escape_attr_val(self.custom_base)}"></base>'

        # Insert head if needed and insert metas
        head_match=re.search(r'<head[^>]*>',html_str,re.IGNORECASE)
        if not head_match:
            html_match=re.search(r'<html[^>]*>',html_str,re.IGNORECASE)
            if html_match:
                insert_pos=html_match.end()
                head_content=""
                if csp_meta:
                    head_content+=csp_meta
                if base_meta:
                    head_content+=base_meta
                if robots_meta:
                    head_content+=robots_meta
                html_str=html_str[:insert_pos]+f"<head>{head_content}</head>"+html_str[insert_pos:]
                csp_meta=base_meta=robots_meta=""
            else:
                head_content=""
                if csp_meta:
                    head_content+=csp_meta
                if base_meta:
                    head_content+=base_meta
                if robots_meta:
                    head_content+=robots_meta
                html_str=f"<head>{head_content}</head>"+html_str
                csp_meta=base_meta=robots_meta=""
        else:
            head_end_match=re.search(r'</head>',html_str,re.IGNORECASE)
