                    def repl_ct(m):
                        full=m.group(0)
                        new_content=f"text/html;charset={enc}"
                        new_tag=re.sub(r'content\s*=\s*("[^"]*"|\'[^\']*\'|[^\s>]+)', f'content="{new_content}"', full, flags=re.IGNORECASE)
                        return new_tag
                    html_str=re.sub(r'<meta[^>]*http-equiv=["\']?Content-Type["\']?[^>]*>', repl_ct, html_str, flags=re.IGNORECASE, count=1)
                else:
                    head_end=re.search(r'</head>',html_str,re.IGNORECASE)
                    if head_end:
                        new_meta=f'<meta charset="{enc}"></meta>'
                        html_str=html_str[:head_end.start()]+new_meta+html_str[head_end.start():]
                    else:
                        html_str=f'<meta charset="{enc}"></meta>'+html_str

        # MHTML wrapping
        if self.options.get('mhtml'):
            mhtml=(
                'MIME-Version: 1.0\n'
                'Content-Type: multipart/related; boundary="----=_NextPart_000_0000"\n'
                '\n'
                '------=_NextPart_000_0000\n'
                'Content-Type: text/html; charset="utf-8"\n'
                'Content-Location: http://example.com/\n'
                '\n'
                f'{html_str}\n'
                '------=_NextPart_000_0000--\n'
            )
            return mhtml
        return html_str

